(()=>{
 const root=document.getElementById('gimnasioventas'); if(!root) return;
 let stage=document.getElementById('salesGymStage'); if(!stage) return;
 // Remove previous listeners by cloning the controls.
 const oldDiff=document.getElementById('salesDifficulty'); let diff=oldDiff;
 if(oldDiff){diff=oldDiff.cloneNode(true); oldDiff.replaceWith(diff)}
 const oldMenu=root.querySelector('#salesCoreMenu,.sales-core-menu,.gym-simple-menu');
 const menu=document.createElement('div'); menu.className='gym-simple-menu sales-core-menu'; menu.id='salesCoreMenuV4';
 menu.innerHTML='<button class="active" data-v4game="demo">🎬 Demo Experience</button>';
 if(oldMenu) oldMenu.replaceWith(menu); else stage.before(menu);
 stage=stage.cloneNode(false); document.getElementById('salesGymStage').replaceWith(stage); stage.id='salesGymStage';
 let level='beginner',game='demo',familyIndex=0,sceneIndex=0;
 const names={beginner:'Principiante',intermediate:'Intermedio',expert:'Experto'};
 const data=window.BLEU_SALES_V4_DATA;
 const state={confidence:65,interest:55,participation:55,energy:90,correct:0};
 function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
 function meters(){return `<div class="sales-live-meters">${[['Confianza',state.confidence],['Interés',state.interest],['Participación',state.participation],['Energía',state.energy]].map(([n,v])=>`<div><span>${n}</span><b>${v}%</b><i><em class="${v>=75?'good':v>=45?'mid':'low'}" style="width:${v}%"></em></i></div>`).join('')}</div>`}
 function apply(d){Object.entries(d||{}).forEach(([k,v])=>state[k]=Math.max(0,Math.min(100,state[k]+v)))}
 function resetState(){Object.assign(state,{confidence:65,interest:55,participation:55,energy:90,correct:0})}
 function familyPicker(){const fams=data[level];stage.innerHTML=`<div class="game-head"><div><span class="game-kicker">Nivel ${names[level]}</span><h3>🎬 Demo Experience</h3></div><span class="badge">15 familias · 15 decisiones únicas</span></div><div class="how-game"><span>ELIGE UNA FAMILIA</span><h4>Cada hogar es una demostración diferente</h4><p>Las 15 preguntas y todas las opciones fueron escritas para esa familia. En ${names[level].toLowerCase()}, la complejidad cambia de verdad.</p></div><div class="v4-family-grid">${fams.map((f,i)=>`<button data-family="${i}"><b>${String(i+1).padStart(2,'0')}</b><strong>${f.name}</strong><small>${f.profile}</small><em>Prioridad: ${f.priority}</em></button>`).join('')}</div>`;stage.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{familyIndex=+b.dataset.family;sceneIndex=0;resetState();renderScene()})}
 function renderScene(){const f=data[level][familyIndex],s=f.scenes[sceneIndex];const order=shuffle(s.options.map((text,i)=>({text,good:i===s.answer})));
 stage.innerHTML=`<div class="game-head"><div><span class="game-kicker">${names[level]} · Familia ${familyIndex+1} de 15</span><h3>${f.name}</h3></div><span class="badge">Decisión ${sceneIndex+1} de 15</span></div>${meters()}<div class="v4-family-story"><strong>${f.profile}</strong><p>${f.problem}</p><span>Prioridad: ${f.priority} · Decisión: ${f.decision}</span></div><div class="sales-question-card"><span class="question-label">${s.stage}</span><div class="case-context">${s.context}</div><h3>${s.question}</h3><div class="game-options sales-varied-options"></div><div class="game-feedback" hidden></div><div class="sales-coach" hidden><article><span>💭 Lo que puede estar pensando la familia</span><p>${s.thought}</p></article><article><span>⭐ Por qué funciona mejor</span><p>${s.why}</p></article><article><span>💡 Entrenamiento</span><p>${s.tip}</p></article></div><button class="primary-action sales-next" hidden>${sceneIndex===14?'Ver resultado':'Continuar'} <span>→</span></button></div>`;
 const box=stage.querySelector('.game-options'),fb=stage.querySelector('.game-feedback'),coach=stage.querySelector('.sales-coach'),next=stage.querySelector('.sales-next');
 order.forEach((o,i)=>{const b=document.createElement('button');b.innerHTML=`<b>${String.fromCharCode(65+i)}</b><span>${o.text}</span>`;b.__good=o.good;b.onclick=()=>{[...box.children].forEach(x=>x.disabled=true);b.classList.add(o.good?'correct':'wrong');if(!o.good)[...box.children].find(x=>x.__good)?.classList.add('correct');apply(o.good?s.goodDelta:s.badDelta);if(o.good)state.correct++;fb.hidden=false;fb.className='game-feedback '+(o.good?'good':'bad');fb.innerHTML=o.good?'✓ <strong>Excelente lectura.</strong> Elegiste la intervención más completa para esta familia.':'Esta respuesta es defendible, pero otra protege mejor la relación y el avance.';coach.hidden=false;next.hidden=false;};box.appendChild(b)});
 next.onclick=()=>{if(sceneIndex<14){sceneIndex++;renderScene()}else finish()};
 }
 function finish(){const f=data[level][familyIndex],pct=Math.round(state.correct/15*100);const ending=pct>=87?'Compra bien conducida y programa sólido':pct>=67?'Interés real, pero quedan puntos por afinar':pct>=47?'La familia pide tiempo para pensarlo':'La confianza se debilitó antes del cierre';stage.innerHTML=`<div class="v4-result"><span>ASÍ TERMINÓ ESTA HISTORIA</span><h3>${f.name}</h3><div class="v4-score">${pct}%</div><h4>${ending}</h4><p>Acertaste ${state.correct} de 15 decisiones. No se evalúa memoria: se evalúa criterio para leer a esta familia.</p>${meters()}<div class="v4-result-actions"><button class="primary-action" id="v4retry">Repetir familia</button><button class="small-action" id="v4families">Elegir otra familia</button></div></div>`;stage.querySelector('#v4retry').onclick=()=>{sceneIndex=0;resetState();renderScene()};stage.querySelector('#v4families').onclick=familyPicker}
 // Keep objection/negotiation modules from v3.5 content by using focused, non-template cases generated from demo data.
 function focused(kind){const fams=data[level],cases=fams.map((f,i)=>{const s=f.scenes[kind==='objections'?11:12];return {f,s,i}});let idx=Math.floor(Math.random()*cases.length),c=cases[idx],s=c.s;stage.innerHTML=`<div class="game-head"><div><span class="game-kicker">${names[level]} · Caso ${idx+1} de 15</span><h3>${kind==='objections'?'🛡️ Objeciones':'🤝 Negociación y cierres'}</h3></div><span class="badge">${c.f.name}</span></div><div class="how-game"><span>SITUACIÓN REAL</span><p>${c.f.problem} Lee todas las opciones: en niveles altos varias son buenas, pero una es más completa.</p></div><div class="sales-question-card"><span class="question-label">${s.stage}</span><div class="case-context">${s.context}</div><h3>${s.question}</h3><div class="game-options sales-varied-options"></div><div class="game-feedback" hidden></div><div class="sales-coach" hidden><article><span>💭 Lectura</span><p>${s.thought}</p></article><article><span>⭐ Mejor criterio</span><p>${s.why}</p></article><article><span>💡 Tip</span><p>${s.tip}</p></article></div><button class="primary-action sales-next" hidden>Otro caso →</button></div>`;const order=shuffle(s.options.map((text,i)=>({text,good:i===s.answer}))),box=stage.querySelector('.game-options'),fb=stage.querySelector('.game-feedback'),coach=stage.querySelector('.sales-coach'),next=stage.querySelector('.sales-next');order.forEach((o,i)=>{const b=document.createElement('button');b.innerHTML=`<b>${String.fromCharCode(65+i)}</b><span>${o.text}</span>`;b.__good=o.good;b.onclick=()=>{[...box.children].forEach(x=>x.disabled=true);b.classList.add(o.good?'correct':'wrong');if(!o.good)[...box.children].find(x=>x.__good)?.classList.add('correct');fb.hidden=false;fb.className='game-feedback '+(o.good?'good':'bad');fb.innerHTML=o.good?'✓ <strong>Muy buena decisión.</strong>':'Había una opción más completa para esta familia.';coach.hidden=false;next.hidden=false};box.appendChild(b)});next.onclick=()=>focused(kind)}
 function render(){familyPicker()}
 diff?.addEventListener('click',e=>{const b=e.target.closest('button[data-level]');if(!b)return;level=b.dataset.level;diff.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()});
 menu.addEventListener('click',e=>{const b=e.target.closest('[data-v4game]');if(!b)return;game=b.dataset.v4game;menu.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()});
 render();
})();
